// Genuine file encoders. Raster SVG deliberately embeds PNG; no vector reconstruction.
export const imageFormats=[['jpg','JPG · Compact photos'],['png','PNG · Lossless, supports transparency'],['webp','WebP · Modern, adjustable quality'],['bmp','BMP · Uncompressed bitmap'],['tiff','TIFF · Uncompressed RGB'],['gif','GIF · Single frame, 256 colors'],['svg','SVG · Embedded page image'],['ico','ICO · Page thumbnail, up to 256 px'],['ppm','PPM · Uncompressed portable pixmap']];
export const textFormats=[['txt','TXT · Plain text'],['docx','DOCX · Word document'],['rtf','RTF · Rich Text Format'],['odt','ODT · OpenDocument Text'],['html','HTML · Web document'],['md','Markdown · Plain text markup'],['json','JSON · Page text data'],['csv','CSV · Page and text columns']];
export const paperSizes={a3:[841.89,1190.55],a4:[595.28,841.89],a5:[419.53,595.28],a6:[297.64,419.53],b4:[708.66,1000.63],b5:[498.9,708.66],letter:[612,792],legal:[612,1008],tabloid:[792,1224],executive:[521.86,756],square:[595.28,595.28]};
export const paperChoices=[['a4','A4'],['a3','A3'],['a5','A5'],['a6','A6'],['b4','ISO B4'],['b5','ISO B5'],['letter','US Letter'],['legal','US Legal'],['tabloid','US Tabloid'],['executive','Executive'],['square','Square · 210 × 210 mm'],['custom','Custom dimensions']];
export function numberIn(value,min,max,label,fallback){const n=value==null||value===''?fallback:Number(value);if(!Number.isFinite(n)||n<min||n>max)throw new Error(`${label} must be between ${min} and ${max}.`);return n;}
export function paperDimensions(v,source=[595.28,841.89]){
 let size=v.paper==='custom'?[numberIn(v.paperWidth,25,1000,'Paper width',210)*72/25.4,numberIn(v.paperHeight,25,1000,'Paper height',297)*72/25.4]:(paperSizes[v.paper]||paperSizes.a4).slice();
 if(v.orientation==='landscape'||(v.orientation==='auto'&&source[0]>source[1]))size=[Math.max(...size),Math.min(...size)];else if(v.orientation==='portrait')size=[Math.min(...size),Math.max(...size)];return size;
}
export function selectedPreset(preset,total){const all=Array.from({length:total},(_,i)=>i+1);return (preset==='odd'?all.filter(n=>n%2):preset==='even'?all.filter(n=>!(n%2)):preset==='first'?[1]:preset==='last'?[total]:all).join(',');}
export function roman(n){if(!Number.isInteger(n)||n<1||n>3999)throw new Error('Roman numerals support numbers from 1 to 3999.');let out='';for(const [v,c]of [[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']])while(n>=v){out+=c;n-=v;}return out;}
export function rgbaToRgb(data){const rgb=new Uint8Array(data.length/4*3);for(let i=0,j=0;i<data.length;i+=4){const a=data[i+3]/255;for(let k=0;k<3;k++)rgb[j++]=Math.round(data[i+k]*a+255*(1-a));}return rgb;}
export function encodeBmp(width,height,rgba,dpi=96){const rgb=rgbaToRgb(rgba),stride=(width*3+3)&~3;const bytes=new Uint8Array(54+stride*height),v=new DataView(bytes.buffer);bytes.set([66,77]);v.setUint32(2,bytes.length,true);v.setUint32(10,54,true);v.setUint32(14,40,true);v.setInt32(18,width,true);v.setInt32(22,height,true);v.setUint16(26,1,true);v.setUint16(28,24,true);v.setUint32(34,stride*height,true);v.setInt32(38,Math.round(dpi/0.0254),true);v.setInt32(42,Math.round(dpi/0.0254),true);for(let y=0;y<height;y++)for(let x=0;x<width;x++){const a=(y*width+x)*3,b=54+(height-1-y)*stride+x*3;bytes[b]=rgb[a+2];bytes[b+1]=rgb[a+1];bytes[b+2]=rgb[a];}return bytes;}
export function encodeTiff(width,height,rgba,dpi=96){const rgb=rgbaToRgb(rgba),count=13,start=8+2+count*12+4,bits=start,xres=start+6,yres=start+14,offset=start+22;const bytes=new Uint8Array(offset+rgb.length),v=new DataView(bytes.buffer);bytes.set([73,73,42,0,8,0,0,0]);v.setUint16(8,count,true);let i=10;for(const[tag,type,n,value]of [[256,4,1,width],[257,4,1,height],[258,3,3,bits],[259,3,1,1],[262,3,1,2],[273,4,1,offset],[277,3,1,3],[278,4,1,height],[279,4,1,rgb.length],[282,5,1,xres],[283,5,1,yres],[284,3,1,1],[296,3,1,2]]){v.setUint16(i,tag,true);v.setUint16(i+2,type,true);v.setUint32(i+4,n,true);if(type===3&&n===1)v.setUint16(i+8,value,true);else v.setUint32(i+8,value,true);i+=12;}v.setUint16(bits,8,true);v.setUint16(bits+2,8,true);v.setUint16(bits+4,8,true);for(const o of[xres,yres]){v.setUint32(o,Math.round(dpi),true);v.setUint32(o+4,1,true);}bytes.set(rgb,offset);return bytes;}
export function encodeGif(width,height,rgba){const rgb=rgbaToRgb(rgba);const header=new Uint8Array(13+768+10+1),v=new DataView(header.buffer);header.set(new TextEncoder().encode('GIF89a'));v.setUint16(6,width,true);v.setUint16(8,height,true);header[10]=247;for(let n=0;n<256;n++){header[13+n*3]=Math.round((n>>5)*255/7);header[14+n*3]=Math.round(((n>>2)&7)*255/7);header[15+n*3]=Math.round((n&3)*255/3);}const o=781;header[o]=44;v.setUint16(o+5,width,true);v.setUint16(o+7,height,true);header[o+10]=8;let bits=0,value=0;const packed=[];const code=n=>{value|=n<<bits;bits+=9;while(bits>=8){packed.push(value&255);value>>>=8;bits-=8;}};code(256);for(let n=0;n<width*height;n++){if(n&&n%200===0)code(256);const j=n*3;code((rgb[j]>>5)<<5|(rgb[j+1]>>5)<<2|(rgb[j+2]>>6));}code(257);if(bits)packed.push(value&255);const blocks=[];for(let n=0;n<packed.length;n+=255){const part=packed.slice(n,n+255);blocks.push(new Uint8Array([part.length,...part]));}return new Blob([header,...blocks,new Uint8Array([0,59])],{type:'image/gif'});}
export function processPixels(canvas,mode='color',threshold=128,contrast=0){if(mode==='color'&&!contrast)return;const ctx=canvas.getContext('2d',{willReadFrequently:true}),pixels=ctx.getImageData(0,0,canvas.width,canvas.height),d=pixels.data;const factor=(259*(contrast+255))/(255*(259-contrast));for(let i=0;i<d.length;i+=4){for(let k=0;k<3;k++)d[i+k]=Math.max(0,Math.min(255,factor*(d[i+k]-128)+128));if(mode!=='color'){let g=Math.round(.2126*d[i]+.7152*d[i+1]+.0722*d[i+2]);if(mode==='bw')g=g>=threshold?255:0;d[i]=d[i+1]=d[i+2]=g;}}ctx.putImageData(pixels,0,0);}
const nativeBlob=(canvas,mime,quality)=>new Promise((resolve,reject)=>canvas.toBlob(b=>b&&b.type===mime?resolve(b):reject(new Error(`This browser cannot encode ${mime}. Choose another format.`)),mime,quality));
export function supportedImageFormats(){const c=document.createElement('canvas');c.width=c.height=1;const formats=imageFormats.filter(([id])=>id!=='webp'||c.toDataURL('image/webp').startsWith('data:image/webp'));if(c.toDataURL('image/avif').startsWith('data:image/avif'))formats.splice(3,0,['avif','AVIF · Browser-supported encoder']);return formats;}
export async function encodeImage(canvas,format,quality=.9,dpi=96){
 const mime={jpg:'image/jpeg',png:'image/png',webp:'image/webp',avif:'image/avif'}[format];if(mime)return nativeBlob(canvas,mime,quality);
 const {width:w,height:h}=canvas;const pixels=()=>canvas.getContext('2d').getImageData(0,0,w,h).data;
 if(format==='bmp')return new Blob([encodeBmp(w,h,pixels(),dpi)],{type:'image/bmp'});
 if(format==='tiff')return new Blob([encodeTiff(w,h,pixels(),dpi)],{type:'image/tiff'});
 if(format==='gif')return encodeGif(w,h,pixels());
 if(format==='ppm')return new Blob([`P6\n${w} ${h}\n255\n`,rgbaToRgb(pixels())],{type:'image/x-portable-pixmap'});
 if(format==='svg'){const png=await nativeBlob(canvas,'image/png');const bytes=new Uint8Array(await png.arrayBuffer());let b64='';for(let i=0;i<bytes.length;i+=8192)b64+=String.fromCharCode(...bytes.subarray(i,i+8192));return new Blob([`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><title>PDF page rendered as an embedded image</title><image width="${w}" height="${h}" href="data:image/png;base64,${btoa(b64)}"/></svg>`],{type:'image/svg+xml'});}
 if(format==='ico'){const c=document.createElement('canvas'),scale=Math.min(1,256/Math.max(w,h));c.width=Math.max(1,Math.round(w*scale));c.height=Math.max(1,Math.round(h*scale));c.getContext('2d').drawImage(canvas,0,0,c.width,c.height);const png=await nativeBlob(c,'image/png'),header=new Uint8Array(22),v=new DataView(header.buffer);v.setUint16(2,1,true);v.setUint16(4,1,true);header[6]=c.width===256?0:c.width;header[7]=c.height===256?0:c.height;v.setUint16(10,1,true);v.setUint16(12,32,true);v.setUint32(14,png.size,true);v.setUint32(18,22,true);return new Blob([header,png],{type:'image/x-icon'});}
 throw new Error('Choose a supported image format.');
}
